                    {
                        <div class="toast success">Password updated successfully!</div>
                    }

                    <button class="btn btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="two-factor-status">
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "●" : "○")
                </span>
                <span>@(_twoFactorEnabled ? "Enabled" : "Disabled")</span>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span>Toggle 2FA</span>
                </label>
            </div>
            @if (_security?.LastPasswordChange is not null)
            {
                <p class="help-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h4>Confirm Session Revocation</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn btn-danger" @onclick="RevokeSessionAsync">Revoke Session</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private const string CurrentSessionId = "sess-1";

    private bool _loading = true;
    private bool _passwordPanelOpen;
    private bool _passwordSuccess;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _twoFactorEnabled;
    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;
    private SecuritySettings? _security;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _security.TwoFactorEnabled;
        _sessions = _security.Sessions.ToList();
        _loading = false;
    }

    private void TogglePasswordPanel() => _passwordPanelOpen = !_passwordPanelOpen;

    private async Task UpdatePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _passwordSuccess = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void ConfirmRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}
