@using sv_f01334353c37464389964ceee0c90b10.Services
@inject ISettingsService SettingsService

<div class="settings-section notifications-section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="notification-toggles">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>
        </div>

        <div class="muted-channels">
            <h3>Muted Channels</h3>
            <p class="help-text">Uncheck channels you want to receive notifications from.</p>
            <ul class="channel-list">
                @foreach (var channel in _channels)
                {
                    <li class="channel-item">
                        <label>
                            <input type="checkbox"
                                   checked="@channel.Muted"
                                   @onchange="(e) => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                            <span>#@channel.Name</span>
                        </label>
                    </li>
                }
            </ul>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Notification preferences saved!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = new();

    private record ChannelState(string Name, bool Muted);

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _channels = prefs.MutedChannels.Select(c => new ChannelState(c, true)).ToList();
        _loading = false;
    }

    private void ToggleChannel(string name, bool muted)
    {
        var index = _channels.FindIndex(c => c.Name == name);
        if (index >= 0)
        {
            _channels[index] = new ChannelState(name, muted);
        }
    }

    private async Task SaveAsync()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

